<?php
declare(strict_types=1);
if(!defined('CWP_BOOT')){http_response_code(404);exit;}
/** Additive declarations only; explicit native preparation/history validation is not implemented here. */
function provider_php_control_lifecycle_schema(string $prefix):array {
    if(preg_match('/\A[a-zA-Z][a-zA-Z0-9_]{1,19}\z/',$prefix)!==1)throw new InvalidArgumentException('Invalid prefix.');
    $id='CHAR(32) CHARACTER SET ascii COLLATE ascii_bin';$hash='CHAR(64) CHARACTER SET ascii COLLATE ascii_bin';$ascii=' CHARACTER SET ascii COLLATE ascii_bin';
    $doc='document_json LONGTEXT'.$ascii.' NOT NULL,document_sha256 '.$hash.' NOT NULL,proof '.$hash.' NOT NULL';
    $actors='actor_staff_id INT UNSIGNED NULL,actor_client_id INT UNSIGNED NULL';
    $tail=' ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci';
    $foreign=static fn(string $p):string=>'INDEX '.$p.'_staff(actor_staff_id),INDEX '.$p.'_client(actor_client_id),FOREIGN KEY (actor_staff_id) REFERENCES `'.$prefix.'users` (id) ON DELETE RESTRICT,FOREIGN KEY (actor_client_id) REFERENCES `'.$prefix.'studio_clients` (id) ON DELETE RESTRICT,CHECK ((actor_staff_id IS NULL) <> (actor_client_id IS NULL))';
    return [
        'provider_php_control_reads'=>'CREATE TABLE `'.$prefix.'provider_php_control_reads` (id '.$id.' PRIMARY KEY,seq BIGINT UNSIGNED NOT NULL AUTO_INCREMENT UNIQUE,profile_id '.$id.' NOT NULL,package_id BIGINT UNSIGNED NOT NULL,link_id '.$id.' NOT NULL,kind VARCHAR(12)'.$ascii.' NOT NULL,'.$actors.',started_epoch BIGINT UNSIGNED NOT NULL,'.$doc.',INDEX php_control_read_resource(profile_id,package_id,kind,seq),INDEX php_control_read_profile_time(profile_id,started_epoch),INDEX php_control_read_staff_time(actor_staff_id,started_epoch),INDEX php_control_read_client_time(actor_client_id,started_epoch),FOREIGN KEY (profile_id) REFERENCES `'.$prefix.'provider_profiles` (id) ON DELETE RESTRICT,'.$foreign('php_control_read').')'.$tail,
        'provider_php_control_read_results'=>'CREATE TABLE `'.$prefix.'provider_php_control_read_results` (read_id '.$id.' PRIMARY KEY,state VARCHAR(12)'.$ascii.' NOT NULL,reason VARCHAR(24)'.$ascii.' NOT NULL,finished_epoch BIGINT UNSIGNED NOT NULL,'.$doc.',FOREIGN KEY (read_id) REFERENCES `'.$prefix.'provider_php_control_reads` (id) ON DELETE RESTRICT)'.$tail,
        'provider_php_changes'=>'CREATE TABLE `'.$prefix.'provider_php_changes` (id '.$id.' PRIMARY KEY,seq BIGINT UNSIGNED NOT NULL AUTO_INCREMENT UNIQUE,profile_id '.$id.' NOT NULL,package_id BIGINT UNSIGNED NOT NULL,link_id '.$id.' NOT NULL,'.$actors.',current_read_id '.$id.' NOT NULL,options_read_id '.$id.' NOT NULL,idempotency_key VARCHAR(190)'.$ascii.' NOT NULL,approved_epoch BIGINT UNSIGNED NOT NULL,expires_epoch BIGINT UNSIGNED NOT NULL,'.$doc.',UNIQUE KEY php_change_key(idempotency_key),INDEX php_change_resource(profile_id,package_id,seq),FOREIGN KEY (profile_id) REFERENCES `'.$prefix.'provider_profiles` (id) ON DELETE RESTRICT,FOREIGN KEY (current_read_id) REFERENCES `'.$prefix.'provider_php_control_reads` (id) ON DELETE RESTRICT,FOREIGN KEY (options_read_id) REFERENCES `'.$prefix.'provider_php_control_reads` (id) ON DELETE RESTRICT,'.$foreign('php_change').')'.$tail,
        'provider_php_dispatch_ends'=>'CREATE TABLE `'.$prefix.'provider_php_dispatch_ends` (request_id '.$id.' PRIMARY KEY,disposition VARCHAR(12)'.$ascii.' NOT NULL,recorded_epoch BIGINT UNSIGNED NOT NULL,'.$actors.',ledger_sha256 '.$hash.' NOT NULL,'.$doc.',FOREIGN KEY (request_id) REFERENCES `'.$prefix.'provider_php_changes` (id) ON DELETE RESTRICT,'.$foreign('php_dispatch_end').')'.$tail,
        'provider_php_change_checks'=>'CREATE TABLE `'.$prefix.'provider_php_change_checks` (id '.$id.' PRIMARY KEY,request_id '.$id.' NOT NULL,read_id '.$id.' NOT NULL,'.$actors.',recorded_epoch BIGINT UNSIGNED NOT NULL,disposition VARCHAR(12)'.$ascii.' NOT NULL,'.$doc.',UNIQUE KEY php_change_check_read(read_id),INDEX php_change_check_request(request_id),FOREIGN KEY (request_id) REFERENCES `'.$prefix.'provider_php_changes` (id) ON DELETE RESTRICT,FOREIGN KEY (read_id) REFERENCES `'.$prefix.'provider_php_control_reads` (id) ON DELETE RESTRICT,'.$foreign('php_change_check').')'.$tail,
    ];
}
